import type { Book, BookStatus } from '../../types';

export const STATUS_LABELS: Record<BookStatus, string> = {
  'want-to-read': 'Want to Read',
  reading: 'Reading',
  read: 'Read',
  abandoned: 'Abandoned',
};

export const SKELETON_COUNT = 6;

export function statusColor(status: BookStatus): string {
  const map: Record<BookStatus, string> = {
    'want-to-read': 'status-want-to-read',
    reading: 'status-reading',
    read: 'status-read',
    abandoned: 'status-abandoned',
  };
  return map[status];
}

interface StatusGroupProps {
  status: BookStatus;
  books: Book[];
}

function StatusGroup({ status, books }: StatusGroupProps): JSX.Element {
  return (
    <section aria-label={STATUS_LABELS[status]}>
      <h2 className={`status-list-heading ${statusColor(status)}`}>
        {STATUS_LABELS[status]}
      </h2>
      <ul className="status-list-items">
        {books.map((book) => (
          <li key={book.id} className="status-list-item">
            <span className="status-list-item-title">{book.title}</span>
            <span className="status-list-item-author">{book.author}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}

function SkeletonItem(): JSX.Element {
  return (
    <li className="status-list-item status-list-item--skeleton" aria-busy="true">
      <span className="status-list-item-title status-list-item-title--skeleton" />
      <span className="status-list-item-author status-list-item-author--skeleton" />
    </li>
  );
}

interface StatusListProps {
  books: Book[] | null;
}

export function StatusList({ books }: StatusListProps): JSX.Element {
  if (books === null) {
    return (
      <section aria-label="Loading books" aria-busy="true">
        <ul className="status-list-items">
          {Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <SkeletonItem key={i} />
          ))}
        </ul>
      </section>
    );
  }

  const statuses: BookStatus[] = ['reading', 'want-to-read', 'read', 'abandoned'];
  const grouped = statuses.reduce<Record<BookStatus, Book[]>>(
    (acc, status) => {
      acc[status] = books.filter((b) => b.status === status);
      return acc;
    },
    { 'want-to-read': [], reading: [], read: [], abandoned: [] },
  );

  return (
    <div className="status-list">
      {statuses
        .filter((status) => grouped[status].length > 0)
        .map((status) => (
          <StatusGroup key={status} status={status} books={grouped[status]} />
        ))}
    </div>
  );
}

