import { useState } from 'react';

type Filter = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTERS: Filter[] = ['All', 'Active', 'Archived', 'Starred'];

export function ChipFilter(): JSX.Element {
  const [pressed, setPressed] = useState<Filter>('All');

  return (
    <>
      <style>{chipFilterStyles}</style>
      <div className="chip-filter" role="group" aria-label="Filter books">
        {FILTERS.map((filter) => (
          <button
            key={filter}
            className="chip-filter-button"
            aria-pressed={pressed === filter}
            onClick={() => setPressed(filter)}
          >
            {filter}
          </button>
        ))}
      </div>
    </>
  );
}

