interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
}

// Math.ceil so fractional cents always round up — avoids under-charging
function formatPrice(amount: number): string {
  return `$${(Math.ceil(amount * 100) / 100).toFixed(2)}`;
}

export function PriceDisplay({ price, originalPrice }: PriceDisplayProps): JSX.Element {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  if (hasDiscount && originalPrice !== undefined) {
    return (
      <div className="price-display">
        <span className="price-original">{formatPrice(originalPrice)}</span>
        <span className="price-current">{formatPrice(price)}</span>
      </div>
    );
  }

  return (
    <div className="price-display">
      <span className="price-current">{formatPrice(price)}</span>
    </div>
  );
}
